@pytest.fixture
def board():
    return BaseBoard()

def test_action_space_1(board: BaseBoard):
    _test_action_space(board, game_1_moves)

def test_action_space_2(board: BaseBoard):
    _test_action_space(board, game_2_moves)

def test_action_space_3(board: BaseBoard):
    _test_action_space(board, game_3_moves)

def _test_action_space(board: BaseBoard, moves: List[str]):
    actions: Dict[int, Move] = {}

    for move_uci in moves:
        move = Move.from_uci(move_uci)

        print(f"Testing move {move}, turn: {COLOR_NAMES[board.turn]}")
        action = encode_move(move)

        if action not in actions:
            actions[action] = move
        else:
            prev_move = actions[action]
            assert prev_move.uci() == move.uci(), f"Action {action} is not unique: {prev_move} and {move}"

        assert action < ACTION_SIZE
        assert action >= 0

        decoded_move = decode_move(action)
        assert move.uci() == decoded_move.uci(), f"Move {move} and decoded move {decoded_move} do not match"

        board.push(decoded_move)
